export type SourceKind = "youtube" | "ambient" | "generated";

export interface Source {
	name: string;
	url: string;
	kind: SourceKind;
}

/**
 * The three streams are the ones the upstream Omarchy widget ships; the rain
 * loops are its CC0 recordings (see `assets/SOUNDS.md`), and the noise is
 * generated by mpv itself.
 */
export const SOURCES: Source[] = [
	{ name: "Lofi hip hop", url: "https://www.youtube.com/watch?v=rFZHOHl-L8A", kind: "youtube" },
	{ name: "Lofi house", url: "https://www.youtube.com/watch?v=3PFJ9SETS4M", kind: "youtube" },
	{ name: "Final Fantasy lofi", url: "https://www.youtube.com/watch?v=gEGQciAcSnI", kind: "youtube" },
	{ name: "Rain", url: "rain.oga", kind: "ambient" },
	{ name: "Rain on roof", url: "rain-roof.oga", kind: "ambient" },
	{ name: "White noise", url: "av://lavfi:anoisesrc=color=white:amplitude=0.06", kind: "generated" },
	{ name: "Brown noise", url: "av://lavfi:anoisesrc=color=brown:amplitude=0.25", kind: "generated" },
];

export const DEFAULT_SOURCE = SOURCES[0]?.url ?? "";

export function sourceName(url: string): string {
	return SOURCES.find((source) => source.url === url)?.name ?? "Custom channel";
}

/** A bundled loop becomes a path under the installed assets directory. */
export function playableUrl(url: string, assetsPath: string): string {
	return url.endsWith(".oga") ? `${assetsPath}/${url}` : url;
}

/**
 * Upstream's mpv invocation: no video, no terminal, loop a plain video, take
 * the best audio track from YouTube through yt-dlp. Everything after `--` is a
 * file or URL, never an option.
 */
export function mpvArgs(url: string, volume: number): string[] {
	return [
		"--no-video",
		"--no-terminal",
		"--loop-file=inf",
		"--ytdl-format=bestaudio/best",
		`--volume=${volume}`,
		"--",
		url,
	];
}
